            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0xC7B4D8BC8379FDEFULL) + aSeedOrbiterUpdateSaltF[(((255U - aIndex) + 53U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x1E781F8108F568CCULL;
