            aOrbiterK = (aWandererF + RotL64(aIngress, 27U)) + 0x9F6B52ABF2C3D3D3ULL;
            aOrbiterD = ((aWandererC + RotL64(aScatter, 13U)) + RotL64(aCarry, 11U)) + 0x78F47D2DECB9FA1EULL;
            aOrbiterF = (((aWandererD + RotL64(aPrevious, 21U)) + RotL64(aCarry, 51U)) + 0x3C783B0C76BE06C5ULL) + aTwistOrbiterAssignSaltB[((aIndex + 208U)) & S_SALT1];
