            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x97A5AC0B0542EF07ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x32772D789FB716CEULL;
            aOrbiterC = RotL64((aOrbiterC * 0xBB78A13E69E8B8C9ULL), 43U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0xB84C2A3DA50FB1A7ULL) + aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 101U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0xF824AAA9B278850DULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC5872F121C9DA5FBULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0xDCAB1AC4915A7C2AULL;
