            aWandererB = aWandererB + ((RotL64(aIngress, 13U) + aOrbiterD) + RotL64(aOrbiterC, 43U));
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 51U) + RotL64(aOrbiterK, 10U)) + aOrbiterF);
