            //
            aCross = (RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 2852U)) & S_BLOCK1], 12U) ^ RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 4998U)) & S_BLOCK1], 51U));
