            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 44U) + RotL64(aCross, 57U)) ^ (RotL64(aPrevious, 5U) + RotL64(aCarry, 19U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterH = ((aWandererG + RotL64(aIngress, 37U)) + RotL64(aCarry, 29U)) + 0xE515887F502EA491ULL;
            aOrbiterG = ((aWandererD + RotL64(aPrevious, 27U)) + 0x152A724B264F0B8EULL) + aTwistOrbiterAssignSaltF[((aIndex + 228U)) & S_SALT1];
            aOrbiterK = ((aWandererJ + RotL64(aCross, 6U)) + RotL64(aCarry, 51U)) + 0x0B2E0B9CAEEE3A98ULL;
