            aWandererK = aWandererK ^ (((RotL64(aCross, 28U) + RotL64(aOrbiterG, 21U)) + aOrbiterJ) + aTwistWandererUpdateSaltC[(((255U - aIndex) + 101U)) & S_SALT1]);
